    25	function BaseModal(
    26	    {
    27	        isVisible,
    28	        onClose,
    29	        shouldSetModalVisibility = true,
    30	        onModalHide = () => {},
    31	        type,
    32	        popoverAnchorPosition = {},
    33	        innerContainerStyle = {},
    34	        outerStyle,
    35	        onModalShow = () => {},
    36	        propagateSwipe,
    37	        fullscreen = true,
