    42	        hideModalContentWhileAnimating = false,
    43	        animationInTiming,
    44	        animationOutTiming,
    45	        statusBarTranslucent = true,
    46	        onLayout,
    47	        avoidKeyboard = false,
    48	        children,
    49	        shouldUseCustomBackdrop = false,
    50	        onBackdropPress,
    51	        modalId,
    52	        shouldEnableNewFocusManagement = false,
    53	        restoreFocusType,
    54	        shouldUseModalPaddingStyle = true,
    55	        initialFocus = false,
    56	    }: BaseModalProps,
    57	    ref: React.ForwardedRef<View>,
    58	) {
    59	    const theme = useTheme();
    60	    const styles = useThemeStyles();
    61	    const StyleUtils = useStyleUtils();
    62	    const {windowWidth, windowHeight} = useWindowDimensions();
    63	    // We need to use isSmallScreenWidth instead of shouldUseNarrowLayout to apply correct modal width
    64	    const {isSmallScreenWidth} = useResponsiveLayout();
    65	    const keyboardStateContextValue = useKeyboardState();
