   126	        // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
   127	        [],
   128	    );
   129	
   130	    const handleShowModal = () => {
   131	        if (shouldSetModalVisibility) {
   132	            Modal.setModalVisibility(true);
   133	        }
   134	        onModalShow();
   135	    };
   136	
   137	    const handleBackdropPress = (e?: KeyboardEvent) => {
   138	        if (e?.key === CONST.KEYBOARD_SHORTCUTS.ENTER.shortcutKey) {
   139	            return;
   140	        }
   141	
   142	        if (onBackdropPress) {
   143	            onBackdropPress();
