   161	        shouldAddTopSafeAreaPadding,
   162	        shouldAddBottomSafeAreaPadding,
   163	        hideBackdrop,
   164	    } = useMemo(
   165	        () =>
   166	            StyleUtils.getModalStyles(
   167	                type,
   168	                {
   169	                    windowWidth,
   170	                    windowHeight,
   171	                    isSmallScreenWidth,
   172	                },
   173	                popoverAnchorPosition,
   174	                innerContainerStyle,
   175	                outerStyle,
   176	            ),
