   178	    );
   179	
   180	    const {
   181	        paddingTop: safeAreaPaddingTop,
   182	        paddingBottom: safeAreaPaddingBottom,
   183	        paddingLeft: safeAreaPaddingLeft,
   184	        paddingRight: safeAreaPaddingRight,
   185	    } = StyleUtils.getSafeAreaPadding(safeAreaInsets);
   186	
   187	    const modalPaddingStyles = shouldUseModalPaddingStyle
   188	        ? StyleUtils.getModalPaddingStyles({
   189	              safeAreaPaddingTop,
   190	              safeAreaPaddingBottom,
   191	              safeAreaPaddingLeft,
   192	              safeAreaPaddingRight,
   193	              shouldAddBottomSafeAreaMargin,
   194	              shouldAddTopSafeAreaMargin,
   195	              shouldAddBottomSafeAreaPadding: !keyboardStateContextValue?.isKeyboardShown && shouldAddBottomSafeAreaPadding,
   196	              shouldAddTopSafeAreaPadding,
   197	              modalContainerStyleMarginTop: modalContainerStyle.marginTop,
   198	              modalContainerStyleMarginBottom: modalContainerStyle.marginBottom,
   199	              modalContainerStylePaddingTop: modalContainerStyle.paddingTop,
   200	              modalContainerStylePaddingBottom: modalContainerStyle.paddingBottom,
   201	              insets: safeAreaInsets,
   202	          })
   203	        : {
   204	              paddingLeft: safeAreaPaddingLeft ?? 0,
   205	              paddingRight: safeAreaPaddingRight ?? 0,
   206	          };
   207	
   208	    const modalContextValue = useMemo(
   209	        () => ({
   210	            activeModalType: isVisible ? type : undefined,
   211	        }),
   212	        [isVisible, type],
   213	    );
   214	
   215	    return (
   216	        <ModalContext.Provider value={modalContextValue}>
   217	            <View
   218	                // this is a workaround for modal not being visible on the new arch in some cases
   219	                // it's necessary to have a non-collapseable view as a parent of the modal to prevent
   220	                // a conflict between RN core and Reanimated shadow tree operations
   221	                // position absolute is needed to prevent the view from interfering with flex layout
   222	                collapsable={false}
   223	                style={[styles.pAbsolute, {zIndex: 1}]}
   224	            >
   225	                <ReactNativeModal
   226	                    // Prevent the parent element to capture a click. This is useful when the modal component is put inside a pressable.
   227	                    onClick={(e) => e.stopPropagation()}
   228	                    onBackdropPress={handleBackdropPress}
   229	                    // Note: Escape key on web/desktop will trigger onBackButtonPress callback
   230	                    // eslint-disable-next-line react/jsx-props-no-multi-spaces
   231	                    onBackButtonPress={Modal.closeTop}
   232	                    onModalShow={handleShowModal}
   233	                    propagateSwipe={propagateSwipe}
   234	                    onModalHide={hideModal}
   235	                    onModalWillShow={saveFocusState}
   236	                    onDismiss={handleDismissModal}
   237	                    onSwipeComplete={() => onClose?.()}
   238	                    swipeDirection={swipeDirection}
   239	                    isVisible={isVisible}
   240	                    backdropColor={theme.overlay}
   241	                    backdropOpacity={!shouldUseCustomBackdrop && hideBackdrop ? 0 : variables.overlayOpacity}
   242	                    backdropTransitionOutTiming={0}
   243	                    hasBackdrop={fullscreen}
   244	                    coverScreen={fullscreen}
   245	                    style={modalStyle}
   246	                    deviceHeight={windowHeight}
   247	                    deviceWidth={windowWidth}
   248	                    animationIn={animationIn ?? modalStyleAnimationIn}
   249	                    animationOut={animationOut ?? modalStyleAnimationOut}
   250	                    // eslint-disable-next-line react-compiler/react-compiler
   251	                    useNativeDriver={useNativeDriverProp && useNativeDriver}
   252	                    // eslint-disable-next-line react-compiler/react-compiler
   253	                    useNativeDriverForBackdrop={useNativeDriverForBackdrop && useNativeDriver}
   254	                    hideModalContentWhileAnimating={hideModalContentWhileAnimating}
   255	                    animationInTiming={animationInTiming}
   256	                    animationOutTiming={animationOutTiming}
   257	                    statusBarTranslucent={statusBarTranslucent}
   258	                    onLayout={onLayout}
   259	                    avoidKeyboard={avoidKeyboard}
   260	                    customBackdrop={shouldUseCustomBackdrop ? <Overlay onPress={handleBackdropPress} /> : undefined}
   261	                >
   262	                    <ModalContent
   263	                        onModalWillShow={saveFocusState}
   264	                        onDismiss={handleDismissModal}
   265	                    >
   266	                        <PortalHost name="modal" />
   267	                        <FocusTrapForModal
   268	                            active={isVisible}
   269	                            initialFocus={initialFocus}
   270	                        >
   271	                            <View
   272	                                style={[styles.defaultModalContainer, modalPaddingStyles, modalContainerStyle, !isVisible && styles.pointerEventsNone]}
   273	                                ref={ref}
   274	                            >
   275	                                <ColorSchemeWrapper>{children}</ColorSchemeWrapper>
   276	                            </View>
   277	                        </FocusTrapForModal>
   278	                    </ModalContent>
   279	                </ReactNativeModal>
   280	            </View>
   281	        </ModalContext.Provider>
   282	    );
   283	}
   284	
   285	BaseModal.displayName = 'BaseModalWithRef';
   286	
   287	export default forwardRef(BaseModal);
