     1	import Onyx from 'react-native-onyx';
     2	import ONYXKEYS from '@src/ONYXKEYS';
     3	
     4	const closeModals: Array<(isNavigating?: boolean) => void> = [];
     5	
     6	let onModalClose: null | (() => void);
     7	let isNavigate: undefined | boolean;
     8	let shouldCloseAll: boolean | undefined;
     9	
    10	/**
    11	 * Allows other parts of the app to call modal close function
    12	 */
    13	function setCloseModal(onClose: () => void) {
    14	    if (!closeModals.includes(onClose)) {
    15	        closeModals.push(onClose);
    16	    }
    17	    return () => {
    18	        const index = closeModals.indexOf(onClose);
    19	        if (index === -1) {
    20	            return;
    21	        }
    22	        closeModals.splice(index, 1);
    23	    };
    24	}
    25	
    26	/**
    27	 * Close topmost modal
    28	 */
    29	function closeTop() {
    30	    if (closeModals.length === 0) {
    31	        return;
    32	    }
    33	    if (onModalClose) {
    34	        closeModals[closeModals.length - 1](isNavigate);
    35	        closeModals.pop();
    36	        return;
    37	    }
    38	    closeModals[closeModals.length - 1]();
    39	    closeModals.pop();
    40	}
    41	
    42	/**
    43	 * Close modal in other parts of the app
    44	 */
    45	function close(onModalCloseCallback: () => void, isNavigating = true, shouldCloseAllModals = false) {
    46	    if (closeModals.length === 0) {
    47	        onModalCloseCallback();
    48	        return;
    49	    }
    50	    onModalClose = onModalCloseCallback;
    51	    shouldCloseAll = shouldCloseAllModals;
    52	    isNavigate = isNavigating;
    53	    closeTop();
    54	}
    55	
    56	function onModalDidClose() {
    57	    if (!onModalClose) {
    58	        return;
    59	    }
    60	    if (closeModals.length && shouldCloseAll) {
    61	        closeTop();
    62	        return;
    63	    }
    64	    onModalClose();
    65	    onModalClose = null;
    66	    isNavigate = undefined;
    67	}
    68	
    69	/**
    70	 * Allows other parts of the app to know when a modal has been opened or closed
    71	 */
    72	function setModalVisibility(isVisible: boolean) {
    73	    Onyx.merge(ONYXKEYS.MODAL, {isVisible});
    74	}
    75	
    76	/**
    77	 * Allows other parts of the app to set whether modals should be dismissable using the Escape key
    78	 */
    79	function setDisableDismissOnEscape(disableDismissOnEscape: boolean) {
    80	    Onyx.merge(ONYXKEYS.MODAL, {disableDismissOnEscape});
    81	}
    82	
    83	/**
    84	 * Allows other parts of app to know that an alert modal is about to open.
    85	 * This will trigger as soon as a modal is opened but not yet visible while animation is running.
    86	 * isPopover indicates that the next open modal is popover or bottom docked
    87	 */
    88	function willAlertModalBecomeVisible(isVisible: boolean, isPopover = false) {
    89	    Onyx.merge(ONYXKEYS.MODAL, {willAlertModalBecomeVisible: isVisible, isPopover});
    90	}
